{"query":"query DroppedCommits($owner: String!, $repo: String!, $number: Int!, $o0: GitObjectID!, $o1: GitObjectID!, $o2: GitObjectID!, $o3: GitObjectID!, $o4: GitObjectID!, $o5: GitObjectID!, $o6: GitObjectID!, $o7: GitObjectID!, $o8: GitObjectID!, $o9: GitObjectID!, $o10: GitObjectID!, $o11: GitObjectID!, $o12: GitObjectID!, $o13: GitObjectID!, $o14: GitObjectID!, $o15: GitObjectID!, $o16: GitObjectID!) {
  repository(owner: $owner, name: $repo) {
    c0: object(oid: $o0) { __typename ... on Commit { ...CommitFields } }
    c1: object(oid: $o1) { __typename ... on Commit { ...CommitFields } }
    c2: object(oid: $o2) { __typename ... on Commit { ...CommitFields } }
    c3: object(oid: $o3) { __typename ... on Commit { ...CommitFields } }
