    c14: object(oid: $o14) { __typename ... on Commit { ...CommitFields } }
    c15: object(oid: $o15) { __typename ... on Commit { ...CommitFields } }
    c16: object(oid: $o16) { __typename ... on Commit { ...CommitFields } }
  }
}

fragment ActorFields on Actor { __typename login }

fragment PageInfoFields on PageInfo { hasNextPage endCursor }

fragment CheckRunFields on CheckRun {
  id
  name
  status
  conclusion
  startedAt
  completedAt
  detailsUrl
  url
  summary
  title
  isRequired(pullRequestNumber: $number)
}

fragment CheckRunsPage on CheckRunConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...CheckRunFields }
}

fragment CheckSuiteFields on CheckSuite {
  id
  status
  conclusion
  createdAt
  updatedAt
  url
  app { slug name }
  push {
    id
    previousSha
    nextSha
    pusher { ...ActorFields }
  }
  workflowRun {
    id
    url
    workflow { name }
  }
  checkRuns(first: 50) { ...CheckRunsPage }
}

fragment CheckSuitesPage on CheckSuiteConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...CheckSuiteFields }
}

fragment CommitFields on Commit {
  id
  oid
  abbreviatedOid
  messageHeadline
  committedDate
  authoredDate
  author {
    name
    user { ...ActorFields }
  }
  checkSuites(first: 10) { ...CheckSuitesPage }
}","variables":{"owner":"cli","repo":"cli","number":14354,"o0":"26b43db58e297003d49bd0824ee8d1ddd5ef95f6","o1":"2cb5bd024650c023a017c77dc556c5947311ec48","o2":"4c88a2e7e1bb6530462bd500064069be9775d738","o3":"8558ed1ef94e92566556439872ada6bf16fc1de8","o4":"8a0fef12625deb9139491d380bf02c2e0c54e65b","o5":"9dc79ee2613f392af512d7d6185d04bc561cd4e7","o6":"9ec2819403a6cf895c4bb52ba732a22d02f57af1","o7":"9f931ecab3d7cc56d06e6940be7790871ce9b09a","o8":"a119f602a7aded11305143e488622c17ccef17a5","o9":"a25c1811112d9f2953bced9fde3e11fe27e18fa5","o10":"a6f38b5e5f3b48d94e79aae5eadc4f4546212de9","o11":"b60d27b685ca1b9e99e51b23baec441cfa302fd2","o12":"c62005ba2dd91b4d83a6a35b443781483838d583","o13":"d4845366f799bdd3219a052d77e14279398f2560","o14":"e1d87ba51573d819f710b37b2a45359fb7e5145c","o15":"e67696bb85e43127785b6de3844cad2e123e9521","o16":"f6e0d8fb60c347a63ab611034834561df97bd813"}}
